INSERT IGNORE INTO materiales(sku,nombre,descripcion,especificacion,unidad,categoria_id) SELECT v.sku,v.nombre,v.nombre,CONCAT(v.size_in,' pulgadas - deck'), 'unidad',c.id FROM (SELECT 'SK8-NEON-80' sku,'Neon Orbit' nombre,'8.0' size_in UNION ALL SELECT 'SK8-CHERRY-825','Cherry Burst','8.25' UNION ALL SELECT 'SK8-NIGHT-80','Night Grid','8.0' UNION ALL SELECT 'SK8-CLOUD-825','Cloud Study','8.25' UNION ALL SELECT 'SK8-DESERT-80','Desert Bloom','8.0' UNION ALL SELECT 'SK8-RADAR-825','Radar Pulse','8.25' UNION ALL SELECT 'SK8-OCEAN-80','Ocean Static','8.0' UNION ALL SELECT 'SK8-BLACK-825','Black Signal','8.25') v JOIN categorias c ON c.nombre='Skateboards demo';
INSERT IGNORE INTO store_products(slug,name,description,product_type,collection_name,featured) VALUES ('neon-orbit','Neon Orbit','Colores eléctricos y una gráfica orbital para destacar en cualquier spot.','DECK','Nuevos gráficos',FALSE),('cherry-burst','Cherry Burst','Rojo cereza y energía limpia para una tabla de calle versátil.','DECK','Nuevos gráficos',FALSE),('night-grid','Night Grid','Retícula oscura con contraste neón y una lectura nocturna.','DECK','Nuevos gráficos',FALSE),('cloud-study','Cloud Study','Formas suaves y composición ligera para una sesión sin ruido.','DECK','Nuevos gráficos',FALSE),('desert-bloom','Desert Bloom','Tonos arena y flores abstractas inspiradas en el desierto.','DECK','Nuevos gráficos',FALSE),('radar-pulse','Radar Pulse','Anillos de radar y color eléctrico para moverte con precisión.','DECK','Nuevos gráficos',FALSE),('ocean-static','Ocean Static','Azules profundos y textura analógica con espíritu costero.','DECK','Nuevos gráficos',FALSE),('black-signal','Black Signal','Una gráfica monocroma y directa para una configuración sobria.','DECK','Nuevos gráficos',FALSE);
INSERT IGNORE INTO store_variants(product_id,material_id,sku,size_in,sale_price_crc,low_stock_threshold,specs_json) SELECT p.id,m.id,m.sku,v.size_in,v.price,2,JSON_OBJECT('material','Arce canadiense','ancho',v.size_in,'tipo','Deck') FROM (SELECT 'neon-orbit' slug,'SK8-NEON-80' sku,'8.0' size_in,29900 price UNION ALL SELECT 'cherry-burst','SK8-CHERRY-825','8.25',30900 UNION ALL SELECT 'night-grid','SK8-NIGHT-80','8.0',28900 UNION ALL SELECT 'cloud-study','SK8-CLOUD-825','8.25',31500 UNION ALL SELECT 'desert-bloom','SK8-DESERT-80','8.0',29500 UNION ALL SELECT 'radar-pulse','SK8-RADAR-825','8.25',32500 UNION ALL SELECT 'ocean-static','SK8-OCEAN-80','8.0',30500 UNION ALL SELECT 'black-signal','SK8-BLACK-825','8.25',28000) v JOIN store_products p ON p.slug=v.slug JOIN materiales m ON m.sku=v.sku;
INSERT IGNORE INTO movimientos_stock(material_id,cantidad,tipo,ubicacion_destino_id,documento,motivo,idempotency_key) SELECT m.id,8,'APERTURA',u.id,'SKATE-DEMO-CATALOG-02','Existencia ficticia de demostracion',CONCAT('seed-skate-opening-02-',m.sku) FROM materiales m JOIN ubicaciones u ON u.codigo='BOD-CENTRAL' WHERE m.sku IN('SK8-NEON-80','SK8-CHERRY-825','SK8-NIGHT-80','SK8-CLOUD-825','SK8-DESERT-80','SK8-RADAR-825','SK8-OCEAN-80','SK8-BLACK-825');
